import jsonimport requestsrequests.packages.urllib3.disable_warnings()url = "https://192.168.122.150/restconf/data/Cisco-IOS-XE-native:native/interface"myheaders = { "Accept": "application/yang-data+json", "Content-type":"application/yang-data+json" }myauth = ("admin", "cisco")NEV = input("Interfész sorszáma: ")DESC = input("Interfész leírása: ")IPCIM = input("IP cím: ")MASZK = input("Netmaszk: ")data = {'Cisco-IOS-XE-native:Loopback':         {'name': int(NEV),          'description': DESC,          'ip':             {'address':                  {'primary':                    {'address': IPCIM,                     'mask': MASZK                    }                   }                  }            }        }resp = requests.post(url, auth=myauth, headers=myheaders, data=json.dumps(data), verify=False)print(resp.status_code)